// No arguments or preconditions are documented for the constructor.
// We mark the instance as alive for downstream validation and lifetime checks.
google_myanmar_tools::ZawgyiDetector *detector = new google_myanmar_tools::ZawgyiDetector();
// Record that this detector is alive and usable
FUZZ_SET_ATTR_INT(detector, "alive", 1);
// detector is returned as an output to the object pool

// Enforce single-destruction: only destroy if the object is marked alive
int alive = FUZZ_GET_ATTR_INT(detector, "alive");
if (!alive) { FUZZ_BAIL(); }
// Destroy the instance; after this, it must not be used
delete detector;
// Do not return any outputs; object is now destroyed

// Validate the detector is a live instance created by the constructor stub
int alive = FUZZ_GET_ATTR_INT(detector, "alive");
if (!alive) { FUZZ_BAIL(); }
// Generate input text. If length == -1, the API likely expects a null-terminated string.
std::string s = FUZZ_PARAM_STR();
// Randomly choose to call with implicit length (-1) or explicit non-negative length
unsigned int mode = *FUZZ_PARAM(unsigned int) % 2;
if (mode == 0) {
    // Null-terminated usage path
    (void)detector->GetZawgyiProbability(s.c_str(), -1);
} else {
    // Explicit-length path; clamp to a reasonable bound
    size_t max_len = s.size();
    size_t cap = max_len < 1024 ? max_len : 1024;
    int32_t len = static_cast<int32_t>(*FUZZ_PARAM(unsigned int) % (cap + 1)); // [0, cap]
    (void)detector->GetZawgyiProbability(s.data(), len);
}
// Return the detector to keep it alive for future calls

// Open a new C API detector handle and validate success
GMTZawgyiDetector *detector = GMTOpenZawgyiDetector();
if (!detector) { FUZZ_BAIL(); }
// Mark this handle as open for downstream checks
FUZZ_SET_ATTR_INT(detector, "open", 1);
// Provide the handle as an output

// Ensure this handle was opened by GMTOpenZawgyiDetector and not yet closed
int open = FUZZ_GET_ATTR_INT(detector, "open");
if (!open) { FUZZ_BAIL(); }
// Close and free resources; do not use the handle after this
GMTCloseZawgyiDetector(detector);
// Not returning the handle removes it from the pool and prevents reuse

// Validate the detector handle is currently open
int open = FUZZ_GET_ATTR_INT(detector, "open");
