import random
import secrets
from typing import List

# This generator focuses on producing valid UTF-8 byte sequences suitable for:
# - google_myanmar_tools::ZawgyiDetector::GetZawgyiProbability (C++)
# - GMTGetZawgyiProbability (C API; expects null-terminated)
# It creates a mixture of:
# - ASCII words/sentences
# - Myanmar script ranges (common for Zawgyi/Unicode detection)
# - Mixed ASCII + Myanmar
# - Strings with embedded NULs possible for explicit-length paths
# - Optional terminal NUL for null-terminated paths
# - Variable lengths up to 1024 (fuzzer caps length to 1024) but we keep <= 4096 overall
# All outputs are valid UTF-8; we avoid malformed encodings.

# Unicode ranges and building blocks
ASCII_PRINTABLE = [*(c for c in map(chr, range(0x20, 0x7F)))]
ASCII_WHITESPACE = [" ", "\t", "\n"]

# Myanmar blocks (commonly used by Zawgyi/Unicode detection)
# Basic Myanmar: U+1000..U+109F
# Extended-A: U+AA60..U+AA7F (rare but valid)
# Extended-B: U+A9E0..U+A9FF (rare but valid)
MYANMAR_BASIC = list(range(0x1000, 0x109F + 1))
MYANMAR_EXT_A = list(range(0xAA60, 0xAA7F + 1))
MYANMAR_EXT_B = list(range(0xA9E0, 0xA9FF + 1))

# Useful punctuation and delimiters
PUNCT = list(".,;:!?()[]{}-—'\"/|@#%&+")

# Some known Myanmar syllable-like patterns (Unicode code points) to encourage valid clusters
# Using common consonants + dependent vowels/medials/tones. These help cover realistic text.
# We keep them as Unicode strings; Python will encode to valid UTF-8.
COMMON_MY_SYLLABLES = [
    "မြန်မာ",  # "Myanmar"
    "ဖက်ဘုတ်",  # mix of stacked consonants
    "ဂျာ",      
    "ကောင်း",   
    "စာ",      
    "တယ်",      
    "မူလ",      
    "မြို့",     
    "ကြီး",      
    "သင်",      
]

# Some English words to mix
EN_WORDS = [
    "hello", "world", "myanmar", "burmese", "unicode", "zawgyi", "text", "language",
    "detector", "probability", "model", "data", "test", "sample", "mixed", "string"
]

# Sampling helpers

def _rand_bool(r: random.Random, p: float) -> bool:
    return r.random() < p


def _choose(r: random.Random, seq: List):
    return seq[r.randrange(len(seq))]


def _rand_ascii_word(r: random.Random) -> str:
    # Mix words and random alphanumerics
    if _rand_bool(r, 0.6):
        return _choose(r, EN_WORDS)
    n = r.randint(1, 12)
    alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
    return "".join(alphabet[r.randrange(len(alphabet))] for _ in range(n))


def _rand_punct(r: random.Random) -> str:
    return _choose(r, PUNCT)


def _rand_my_codepoint(r: random.Random) -> int:
    bucket = r.random()
    if bucket < 0.8:
        return _choose(r, MYANMAR_BASIC)
    elif bucket < 0.95:
        return _choose(r, MYANMAR_EXT_A)
    else:
        return _choose(r, MYANMAR_EXT_B)


def _rand_my_cluster(r: random.Random) -> str:
    # Occasionally pick a known good syllable
    if _rand_bool(r, 0.4):
        return _choose(r, COMMON_MY_SYLLABLES)
    # Otherwise build a small cluster: base consonant + optional medials/diacritics
    # We keep it simple to remain valid Unicode sequences.
    base = chr(_choose(r, list(range(0x1000, 0x102A + 1))))  # consonants + vowels
    parts = [base]
    # Optional medials: U+103B..U+103E
    medials = [0x103B, 0x103C, 0x103D, 0x103E]
    r.shuffle(medials)
    for m in medials:
        if _rand_bool(r, 0.3):
            parts.append(chr(m))
    # Vowel signs: U+102B..U+1030, U+1032, U+1036..U+1038
    vowels = [*range(0x102B, 0x1031), 0x1032, *range(0x1036, 0x1039)]
    if _rand_bool(r, 0.7):
        parts.append(chr(_choose(r, vowels)))
    # Asat U+103A, tone marks U+1037/U+1038, dot below U+1037 already covered
    if _rand_bool(r, 0.4):
        parts.append(chr(0x103A))
    if _rand_bool(r, 0.3):
        parts.append(chr(0x1037))
    if _rand_bool(r, 0.2):
        parts.append(chr(0x1038))
    return "".join(parts)


def _rand_my_text(r: random.Random, target_chars: int) -> str:
    tokens: List[str] = []
    while len("".join(tokens)) < target_chars:
        choice = r.random()
        if choice < 0.65:
            tokens.append(_rand_my_cluster(r))
        elif choice < 0.75:
            tokens.append(_choose(r, COMMON_MY_SYLLABLES))
        elif choice < 0.85:
            tokens.append(_rand_punct(r))
        else:
            tokens.append(_choose(r, ASCII_WHITESPACE))
    return "".join(tokens)


def _rand_ascii_text(r: random.Random, target_chars: int) -> str:
    words = []
    while sum(len(w) for w in words) + max(0, len(words) - 1) < target_chars:
        words.append(_rand_ascii_word(r))
    sep = _choose(r, [" ", ", ", "; ", "\n"]) if _rand_bool(r, 0.7) else " "
    s = sep.join(words)
    # Add punctuation at end sometimes
    if _rand_bool(r, 0.5):
        s += _rand_punct(r)
    return s


def _rand_mixed_text(r: random.Random, target_chars: int) -> str:
    parts: List[str] = []
    while len("".join(parts)) < target_chars:
        if _rand_bool(r, 0.5):
            parts.append(_rand_my_text(r, r.randint(5, 20)))
        else:
            parts.append(_rand_ascii_text(r, r.randint(5, 20)))
        if _rand_bool(r, 0.6):
            parts.append(_choose(r, [" ", "\n"]))
    return "".join(parts)


def _insert_embedded_nuls(r: random.Random, b: bytes, max_inserts: int = 3) -> bytes:
    # For explicit-length API paths, embedded NUL bytes should be acceptable.
    if not b:
        return b
    inserts = r.randint(0, max_inserts)
    ba = bytearray(b)
    for _ in range(inserts):
        pos = r.randrange(0, len(ba)+1)
        ba[pos:pos] = b"\x00"
    return bytes(ba)


def _maybe_terminate_null(r: random.Random, b: bytes) -> bytes:
    # C API expects null-terminated when used via c_str(); ensure null termination sometimes.
    if not b or b[-1] != 0:
        if _rand_bool(r, 0.7):
            return b + b"\x00"
    return b


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Decide overall content style
    style = r.choices(
        population=["myanmar", "ascii", "mixed"],
        weights=[0.5, 0.2, 0.3],
        k=1,
    )[0]

    # Decide target character count before encoding
    # Keep within a limit so that after UTF-8 encoding and optional NULs we stay <= 4096
    target_chars = r.randint(10, 800)

    if style == "myanmar":
        text = _rand_my_text(r, target_chars)
    elif style == "ascii":
        text = _rand_ascii_text(r, target_chars)
    else:
        text = _rand_mixed_text(r, target_chars)

    # Encode to UTF-8 (valid by construction)
    data = text.encode("utf-8")

    # Occasionally add embedded NULs to support explicit-length fuzz path variety
    if _rand_bool(r, 0.4):
        data = _insert_embedded_nuls(r, data, max_inserts=5)

    # Optionally ensure null-termination to exercise c_str() paths
    data = _maybe_terminate_null(r, data)

    # Ensure size bounds
    if len(data) > 4096:
        data = data[:4095]  # leave room for optional terminator adjustment next
        data = _maybe_terminate_null(r, data.rstrip(b"\x00"))
        data = data[:4096]

    return data

import random
from typing import List, Tuple

# This generator produces interesting UTF-8 and binary byte sequences suitable for:
# - ZawgyiDetector::GetZawgyiProbability with length -1 (expects null-terminated UTF-8-ish text)
# - ZawgyiDetector::GetZawgyiProbability with explicit length
# - GMTGetZawgyiProbabilityWithLength with explicit length
# It returns a single bytes object that the fuzzer will use as FUZZ_PARAM_STR/FILENAME backing data.
# We bias toward valid UTF-8 with Myanmar ranges and Zawgyi-related code points, but also include
# edge cases: empty, very short, long repeats, mixed scripts, ASCII, control chars, and embedded NULs.

MYANMAR_BLOCKS: List[Tuple[int, int]] = [
    (0x1000, 0x109F),   # Myanmar
    (0xAA60, 0xAA7F),   # Myanmar Extended-A
    (0xA9E0, 0xA9FF),   # Myanmar Extended-B
]

# Common Myanmar digits, letters, medials, vowels that can form valid-looking sequences.
MYANMAR_PRIMES: List[int] = [
    0x1000, 0x1001, 0x1002, 0x1004, 0x1005, 0x1007, 0x100A, 0x1010, 0x1015, 0x1019, 0x101A, 0x101B,
    0x101D, 0x1021, 0x1023, 0x1025, 0x1027, 0x102D, 0x102E, 0x102F, 0x1030, 0x1031, 0x1032, 0x1036,
    0x1037, 0x1038, 0x1039, 0x103A, 0x103B, 0x103C, 0x103D, 0x103E, 0x1040, 0x1041, 0x1042, 0x1044,
    0x104A, 0x104B, 0x104D, 0x1050, 0x105A,
]

ASCII_WORDS = [
    b"hello ", b"world ", b"test ", b"abc ", b"Myanmar ", b"Zawgyi ", b"Unicode ", b"detector ",
]

# Known Zawgyi-ish code points (ordering patterns used below)
ZAWGYIISH_CODEPOINTS = [0x1031, 0x103B, 0x103C, 0x103D, 0x103E, 0x1000, 0x1004, 0x1015, 0x1019, 0x102D, 0x102F, 0x1030, 0x1037, 0x1038]


def _rand_unicode_in_ranges(rng: random.Random, ranges: List[Tuple[int, int]]) -> int:
    lo, hi = rng.choice(ranges)
    return rng.randint(lo, hi)


def _encode_cp(cp: int) -> bytes:
    return chr(cp).encode('utf-8', 'strict')


def _gen_myanmar_word(rng: random.Random, max_syllables: int = 4) -> bytes:
    syllables = rng.randint(1, max_syllables)
    out = bytearray()
    for _ in range(syllables):
        # Optional pre-vowel 1031
        if rng.random() < 0.4:
            out += _encode_cp(0x1031)
        # Base consonant
        base = rng.choice(MYANMAR_PRIMES[:15])  # emphasize common consonants
        out += _encode_cp(base)
        # Random medials
        for cp in [0x103B, 0x103C, 0x103D, 0x103E]:
            if rng.random() < 0.3:
                out += _encode_cp(cp)
        # Vowels
        for cp in [0x102D, 0x102E, 0x102F, 0x1030]:
            if rng.random() < 0.25:
                out += _encode_cp(cp)
        # Asat / virama
        if rng.random() < 0.15:
            out += _encode_cp(0x103A)
        # Tone marks
        if rng.random() < 0.3:
            out += _encode_cp(0x1037)
        if rng.random() < 0.25:
            out += _encode_cp(0x1038)
        # Sometimes punctuation
        if rng.random() < 0.2:
            out += _encode_cp(0x104A)
    return bytes(out)


def _gen_zawgyiish(rng: random.Random, length_hint: int) -> bytes:
    # Construct sequences with ordering often seen in Zawgyi encodings.
    out = bytearray()
    while len(out) < length_hint:
        seq = [0x1031] if rng.random() < 0.6 else []
        seq += [rng.choice([0x1000, 0x1004, 0x1015, 0x1019])]
        # Zawgyi-ish stacking: include multiple medials possibly before base
        medials = [cp for cp in [0x103B, 0x103C, 0x103D, 0x103E] if rng.random() < 0.6]
        seq = medials + seq
        # Vowels and tones in flexible order
        tail = [cp for cp in [0x102D, 0x102F, 0x1030, 0x1037, 0x1038] if rng.random() < 0.5]
        seq += tail
        for cp in seq:
            out += _encode_cp(cp)
        if rng.random() < 0.2:
            out += b" "
    return bytes(out[:length_hint])


def _gen_ascii_phrase(rng: random.Random, max_words: int = 12) -> bytes:
    words = rng.randint(1, max_words)
    out = bytearray()
    for _ in range(words):
        out += rng.choice(ASCII_WORDS)
    return bytes(out.rstrip())


def _gen_myammar_token(rng: random.Random) -> bytes:
    # Sometimes a full word, sometimes short token
    if rng.random() < 0.7:
        return _gen_myanmar_word(rng, max_syllables=rng.randint(1, 5))
    else:
        cps = [rng.choice(MYANMAR_PRIMES) for _ in range(rng.randint(1, 3))]
        return b"".join(_encode_cp(c) for c in cps)


def _gen_myammar_or_single(rng: random.Random) -> bytes:
    if rng.random() < 0.5:
        return _gen_myammar_token(rng)
    else:
        cp = _rand_unicode_in_ranges(rng, MYANMAR_BLOCKS)
        return _encode_cp(cp)


def _gen_mixed_scripts(rng: random.Random, length_hint: int) -> bytes:
    out = bytearray()
    while len(out) < length_hint:
        choice = rng.random()
        if choice < 0.4:
            out += _gen_myammar_or_single(rng)
        elif choice < 0.7:
            out += _gen_ascii_phrase(rng, max_words=3) + b" "
        else:
            # Other scripts: random BMP letters (e.g., Cyrillic)
            cp = rng.randint(0x0400, 0x04FF)
            out += _encode_cp(cp)
        if rng.random() < 0.15:
            out += b"\x00"  # embedded NUL (explicit-length paths)
    return bytes(out[:length_hint])


def _gen_binary_with_utf8_islands(rng: random.Random, length_hint: int) -> bytes:
    out = bytearray()
    while len(out) < length_hint:
        if rng.random() < 0.6:
            # Insert a small valid UTF-8 island (Myanmar or ASCII)
            if rng.random() < 0.5:
                out += _gen_myammar_or_single(rng)
            else:
                out += _gen_ascii_phrase(rng, max_words=2)
        else:
            # Random binary chunk
            sz = rng.randint(1, 16)
            out += bytes(rng.getrandbits(8) for _ in range(sz))
    return bytes(out[:length_hint])


def _gen_null_terminated_utf8(payload: bytes) -> bytes:
    # Ensure exactly one terminal NUL at end and avoid interior NULs for this case
    body = payload.replace(b"\x00", b"")
    return body + b"\x00"


def _choose_template(rng: random.Random) -> bytes:
    # Weighted selection of content templates
    templates = [
        (0.18, lambda: _gen_myanmar_word(rng, max_syllables=rng.randint(1, 8))),
        (0.16, lambda: _gen_zawgyiish(rng, length_hint=rng.randint(12, 256))),
        (0.16, lambda: _gen_mixed_scripts(rng, length_hint=rng.randint(20, 512))),
        (0.14, lambda: _gen_ascii_phrase(rng, max_words=rng.randint(2, 30))),
        (0.12, lambda: b""),  # empty input
        (0.12, lambda: _gen_binary_with_utf8_islands(rng, length_hint=rng.randint(8, 512))),
        (0.12, lambda: b"\x00" * rng.randint(1, 64)),  # NUL run
    ]
    r = rng.random()
    acc = 0.0
    for w, fn in templates:
        acc += w
        if r < acc:
            return fn()
    return templates[-1][1]()


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide the overall size cap (limit to 4096 per instructions, pick smaller typical sizes)
    cap = rng.choice([64, 128, 256, 512, 1024, 2048, 3072])

    payload = _choose_template(rng)

    # Occasionally build longer repeated patterns to exercise Markov transitions
    if rng.random() < 0.35 and len(payload) > 0:
        reps = rng.randint(2, max(2, min(20, cap // max(1, len(payload)))))
        glue = b" " if (b"\x00" not in payload) else b""
        payload = (payload + glue) * reps

    # Mix in separators or punctuation
    if rng.random() < 0.5 and len(payload) > 0:
        sep_choices = [b" ", b"\n", b"\r\n", b"\t", _encode_cp(0x104A), _encode_cp(0x104B)]
        parts = []
        for _ in range(rng.randint(1, 5)):
            cut = rng.randint(0, len(payload))
            parts.append(payload[:cut])
        payload = b"".join(p + rng.choice(sep_choices) for p in parts) + payload

    # Cap the size
    payload = payload[:cap]

    # 50% chance to return as-is (explicit-length path friendly), 50% ensure null-terminated for length -1 path
    if rng.random() < 0.5:
        # As-is; may include embedded NULs
        return bytes(payload)
    else:
        return _gen_null_terminated_utf8(payload)
